// Station 1.5, Selbst bauen: ein Baum aus lauter kleineren Bäumen.
// Ändere die drei Werte. Sage vorher, wie sich das Bild ändert, dann starte.
int stufe = 6;          // Wie oft verzweigt sich der Baum?
double winkel = 25;     // Wie weit spreizen sich die Äste (in Grad)?
double faktor = 0.7;    // Um welchen Faktor wird jeder Ast kürzer?

World welt = new World(800, 600);
welt.setBackgroundColor(Color.white);
Turtle t = new Turtle(400, 590, false);
t.turn(90);                         // nach oben schauen
t.setBorderColor(Color.saddlebrown);
Fraktal.ast(t, 160, stufe, winkel, faktor);
println("Gezeichnete Äste: " + Fraktal.aeste);

/**
 * Verzweigte Rekursion als Bild: Jeder Ast trägt zwei kleinere Bäume.
 */
public class Fraktal {
   public static int aeste = 0;

   // Zeichnet einen Ast und darauf zwei kleinere Bäume.
   // Danach steht die Turtle wieder genau dort, wo sie angefangen hat, und schaut in dieselbe Richtung.
   public static void ast(Turtle t, double laenge, int stufe, double winkel, double faktor) {
      if (stufe == 0) {                  // Abbruchbedingung
         return;
      }
      aeste++;
      t.forward(laenge);                 // ① Ast zeichnen
      t.turn(winkel);                    // ② nach links drehen
      ast(t, laenge * faktor, stufe - 1, winkel, faktor);   // ③ linker Baum
      t.turn(-2 * winkel);               // ④ nach rechts drehen
      ast(t, laenge * faktor, stufe - 1, winkel, faktor);   // ⑤ rechter Baum
      t.turn(winkel);                    // ⑥ wieder geradeaus
      t.forward(-laenge);                // ⑦ zurück zum Anfang des Asts
   }
}
